```java
// DTO
@Data
public class CreateOrderRequest {
    @NotNull(message = "用户ID不能为空")
    private Long userId;

    @NotNull(message = "商品ID不能为空")
    private Long productId;

    @Min(value = 1, message = "数量至少为1")
    private Integer quantity;
}

// VO
public record OrderVO(Long id, Long userId, Long productId,
                      Integer quantity, OrderStatus status, LocalDateTime createTime) {}

// 枚举
public enum OrderStatus {
    PENDING(0), CONFIRMED(1), PAID(2), CANCELLED(-1);
    private final int code;
    // ...
}

// Controller — 只负责接收和返回
@RestController
@RequestMapping("/api/orders")
@RequiredArgsConstructor
public class OrderController {
    private final OrderService orderService;

    @PostMapping
    public ResponseEntity<OrderVO> create(@RequestBody @Valid CreateOrderRequest request) {
        OrderVO order = orderService.create(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(order);
    }
}

// Service — 业务逻辑和事务
@Service
@RequiredArgsConstructor
public class OrderService {
    private final OrderMapper orderMapper;

    @Transactional(rollbackFor = Exception.class)
    public OrderVO create(CreateOrderRequest request) {
        Order order = new Order();
        order.setUserId(request.getUserId());
        order.setProductId(request.getProductId());
        order.setQuantity(request.getQuantity());
        order.setStatus(OrderStatus.PENDING);
        orderMapper.insert(order);
        return toVO(order);
    }
}
```
